const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '解一元一次方程' },
      { kind: 'text', payload: '4x+1=1x+9' },
      { kind: 'text', payload: '1' },
      { kind: 'text', payload: '移项' },
      { kind: 'text', payload: '4x − 1x = 9 − 1' },
      { kind: 'text', payload: '2' },
      { kind: 'text', payload: '合并同类项' },
      { kind: 'text', payload: '3x = 8' },
      { kind: 'text', payload: '3' },
      { kind: 'text', payload: '系数化为 1' },
      { kind: 'text', payload: 'x = 8/3' }
    ];
  },
  render: function (input, metrics) {
    var vp = (input && input.viewport) || { widthDu: 720, heightDu: 900 };
    var W = vp.widthDu, H = vp.heightDu;
    var mAll = Math.max(8, Math.min(W, H) * 0.045);
    var cardX = mAll, cardY = mAll;
    var cardW = Math.max(60, W - mAll * 2);
    var cardH = Math.max(60, H - mAll * 2);
    var base = Math.min(cardW * 0.030, cardH * 0.026);
    if (!isFinite(base) || base <= 0) { base = 14; }

    function mw(i, fallback) {
      var m = metrics && metrics[i];
      if (typeof m === 'number' && isFinite(m) && m > 0) { return m; }
      if (m && typeof m.width === 'number' && isFinite(m.width) && m.width > 0) { return m.width; }
      return fallback;
    }

    function rectPts(x, y, w, h) {
      return [[x, y], [x + w, y], [x + w, y + h], [x, y + h], [x, y]];
    }

    var paths = [];
    var children = [];

    function addPath(id, cmds, style) {
      paths.push({ id: id, commands: cmds });
      var node = { type: 'path', pathId: id };
      if (style) {
        for (var k in style) {
          if (Object.prototype.hasOwnProperty.call(style, k)) { node[k] = style[k]; }
        }
      }
      children.push(node);
    }

    function addLabel(text, x, y, size, fill, anchor) {
      children.push({
        type: 'label', text: text, x: x, y: y, fontSize: size,
        fill: fill, anchor: anchor, textAnchor: anchor
      });
    }

    addPath('card', visualSdk.polyline(rectPts(cardX, cardY, cardW, cardH)),
      { fill: '#ffffff', stroke: '#d5deee', strokeWidth: 1.5 });

    var fsTitle = base * 1.05;
    var titleY = cardY + cardH * 0.075;
    addLabel('解一元一次方程', cardX + cardW / 2, titleY, fsTitle, '#5a6b85', 'middle');

    var bandX = cardX + cardW * 0.08;
    var bandW = cardW * 0.84;
    var bandH = cardH * 0.125;
    var bandY = cardY + cardH * 0.095;
    addPath('band', visualSdk.polyline(rectPts(bandX, bandY, bandW, bandH)),
      { fill: '#eaf1fd', stroke: '#c9d9f5', strokeWidth: 1.2 });

    var fsEq = Math.min(base * 1.85, bandW / 8.5);
    if (!isFinite(fsEq) || fsEq <= 0) { fsEq = base * 1.6; }
    addLabel('4x+1=1x+9', cardX + cardW / 2, bandY + bandH / 2 + fsEq * 0.36, fsEq, '#16325c', 'middle');

    var stepsTop = cardY + cardH * 0.30;
    var stepH = cardH * 0.15;
    var stepGap = cardH * 0.068;
    var blockX = cardX + cardW * 0.055;
    var blockW = cardW * 0.89;

    var names = ['移项', '合并同类项', '系数化为 1'];
    var values = ['4x − 1x = 9 − 1', '3x = 8', 'x = 8/3'];

    var fsStep = base * 1.0;
    var fsValMax = base * 1.28;

    for (var i = 0; i < 3; i++) {
      var by = stepsTop + i * (stepH + stepGap);
      addPath('blk' + i, visualSdk.polyline(rectPts(blockX, by, blockW, stepH)),
        { fill: '#f7faff', stroke: '#dbe4f3', strokeWidth: 1.2 });
      addPath('bar' + i, visualSdk.polyline(rectPts(blockX, by, Math.max(3, stepH * 0.05), stepH)),
        { fill: '#2f6feb', stroke: 'none' });

      var r = stepH * 0.26;
      var bcx = blockX + stepH * 0.34 + r;
      var bcy = by + stepH / 2;
      addPath('badge' + i, visualSdk.circle(bcx, bcy, r), { fill: '#2f6feb', stroke: 'none' });
      addLabel(String(i + 1), bcx, bcy + fsStep * 0.36, fsStep * 0.95, '#ffffff', 'middle');

      var nameX = bcx + r + stepH * 0.22;
      addLabel(names[i], nameX, bcy + fsStep * 0.36, fsStep, '#26354a', 'start');

      var vfs = Math.min(fsValMax, (blockW * 0.50) / (values[i].length * 0.60));
      if (!isFinite(vfs) || vfs <= 0) { vfs = fsValMax; }
      var valCx = blockX + blockW * 0.68;
      addLabel(values[i], valCx, bcy + vfs * 0.36, vfs, '#0f3d8a', 'middle');

      if (i < 2) {
        var ax = blockX + blockW * 0.5;
        var y1 = by + stepH + stepGap * 0.16;
        var y2 = by + stepH + stepGap * 0.84;
        addPath('arw' + i, visualSdk.arrow(ax, y1, ax, y2, {}),
          { stroke: '#9db4d8', strokeWidth: 1.6, fill: '#9db4d8' });
      }
    }

    return {
      schemaVersion: 1,
      sceneId: 'linear-equation-flow',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
